from .models import Product, Base
from sqlalchemy.orm import Session
from sqlalchemy import create_engine

# PUBLIC_INTERFACE
def seed_shirt_products():
    """Seeds 10 shirt products with name, description, price, and image to the database."""
    # Placeholder images from Unsplash or similar quality open sources
    shirt_images = [
        "https://images.unsplash.com/photo-1512436991641-6745cdb1723f?auto=format&fit=crop&w=500&q=80",
        "https://images.unsplash.com/photo-1521572261258-9fe09a00e8e6?auto=format&fit=crop&w=500&q=80",
        "https://images.unsplash.com/photo-1517841905240-472988babdf9?auto=format&fit=crop&w=500&q=80",
        "https://images.unsplash.com/photo-1529626455594-4ff0802cfb7e?auto=format&fit=crop&w=500&q=80",
        "https://images.unsplash.com/photo-1465101046530-73398c7f28ca?auto=format&fit=crop&w=500&q=80",
        "https://images.unsplash.com/photo-1484516757781-9a9a97e8d8b3?auto=format&fit=crop&w=500&q=80",
        "https://images.unsplash.com/photo-1454023492550-5696f8ff10e1?auto=format&fit=crop&w=500&q=80",
        "https://images.unsplash.com/photo-1469398715555-76331e8556c7?auto=format&fit=crop&w=500&q=80",
        "https://images.unsplash.com/photo-1475189778702-4bbf64a6ec6d?auto=format&fit=crop&w=500&q=80",
        "https://images.unsplash.com/photo-1503342452485-86a096e80b1b?auto=format&fit=crop&w=500&q=80"
    ]
    shirts = [
        {
            "name": "Classic White Shirt",
            "description": "Timeless comfort with a clean look.",
            "price": 29.99,
            "category": "shirt",
            "image_url": shirt_images[0]
        },
        {
            "name": "Slim Fit Blue Shirt",
            "description": "A stylish slim-fit shirt, ideal for any occasion.",
            "price": 34.99,
            "category": "shirt",
            "image_url": shirt_images[1]
        },
        {
            "name": "Plaid Casual Shirt",
            "description": "Relaxed fit with classic plaid style.",
            "price": 27.50,
            "category": "shirt",
            "image_url": shirt_images[2]
        },
        {
            "name": "Black Sport Shirt",
            "description": "A sporty black shirt for both workout and leisure.",
            "price": 30.00,
            "category": "shirt",
            "image_url": shirt_images[3]
        },
        {
            "name": "Light Denim Shirt",
            "description": "Casual denim shirt for easygoing days.",
            "price": 32.45,
            "category": "shirt",
            "image_url": shirt_images[4]
        },
        {
            "name": "V-neck Stretch Shirt",
            "description": "Soft stretch fabric with modern v-neck cut.",
            "price": 28.90,
            "category": "shirt",
            "image_url": shirt_images[5]
        },
        {
            "name": "Long Sleeve Green Shirt",
            "description": "Everyday comfort with extra coverage.",
            "price": 31.50,
            "category": "shirt",
            "image_url": shirt_images[6]
        },
        {
            "name": "Short Sleeve Yellow Shirt",
            "description": "Bright color, great for sunny days.",
            "price": 25.00,
            "category": "shirt",
            "image_url": shirt_images[7]
        },
        {
            "name": "Red Checked Shirt",
            "description": "Bold pattern, soft woven fabric.",
            "price": 29.25,
            "category": "shirt",
            "image_url": shirt_images[8]
        },
        {
            "name": "Olive Oversized Shirt",
            "description": "Oversized fit for trendy, relaxed look.",
            "price": 35.00,
            "category": "shirt",
            "image_url": shirt_images[9]
        }
    ]

    # Retrieve database URL from environment or use default local SQLite
    db_url = os.getenv("DATABASE_URL", "sqlite:///../sports_gear.db")
    engine = create_engine(db_url)
    Base.metadata.create_all(bind=engine)

    with Session(autocommit=False, autoflush=True, bind=engine) as db:
        for shirt in shirts:
            exists = db.query(Product).filter_by(name=shirt['name']).first()
            if not exists:
                db.add(Product(
                    name=shirt["name"],
                    description=shirt["description"],
                    price=shirt["price"],
                    category=shirt["category"],
                    image_url=shirt["image_url"]
                ))
        db.commit()


